ENGLISH = 'ETAOINSHRDLCUMWFGYPBVKJXQZ'  # 빈도 순

def freq_guess(cipher):
    cnt = {}
    for ch in cipher.upper():
        if ch.isalpha():
            cnt[ch] = cnt.get(ch, 0) + 1
    ranked = sorted(cnt, key=cnt.get, reverse=True)
    # 빈도 순위끼리 대응 → 초기 추정 키
    key = {c: ENGLISH[i] for i, c in enumerate(ranked)}
    # 이후 단어 패턴으로 수동 보정
    return ''.join(key.get(ch, ch) for ch in cipher.upper())
